from pathlib import Path
import html, json

root=Path(__file__).parent
rows=[]
def add(page,title,status,before,after,why,path,extra=''):
    rows.append(dict(page=page,title=title,status=status,before=before,after=after,why=why,url='https://www.netstim.org/'+path,extra=extra))

add('Site-wide','Institutional name','Update','Page titles use “Network Stimulation Laboratory”.','NetStim — Institute for Network Stimulation','Align page titles with the institute identity already used on the homepage. Keep informal references to the lab.','','https://uni-koeln.de/universitaet/aktuell/personalia/personalia-news-detail/professor-dr-andreas-horn')
add('Home','Opening','Editorial','The homepage starts with a salutation; Cologne is already correct.','Understanding brain networks. Improving brain stimulation.\n\nWe are the Institute for Network Stimulation at University Hospital Cologne. Our research brings together neuroimaging, computational methods and neuromodulation.','Optional clearer introduction, not a correction of the existing location. The headline expresses a research aim.','')
add('Home','Publication highlights','Editorial','Prestige of publication venues takes precedence over research findings.','Selected research\n\nPresent three to six team-selected papers with title, year, publication status and a short description of the question addressed. Link to the complete bibliography.','Choose papers after reviewing the bibliography; do not invent a latest-publications list.','')
add('Home','Funding','Confirm','The funder list is undated and repeats the German Research Council.','Remove the repeated entry. Have the grant administrator confirm current and completed awards; add award periods and a review date.','Duplication is visible. Current funding status cannot be inferred from a member’s personal grant.','')
add('People','Andreas: current appointment','Update','Biography foregrounds training and former appointments.','Andreas holds the Schilling Professorship in Computational Neurology at the University of Cologne, which he took up in May 2025.','Lead with the appointment; retain the career history below.','about-us/about-us/','https://uni-koeln.de/universitaet/aktuell/personalia/personalia-news-detail/professor-dr-andreas-horn')
add('People','Aysu: conflicting career stages','Confirm','Opening identifies a Berlin doctoral student; later text describes a Cologne postdoc and future PhD plans.','Replace the opening and future-tense degree references together after Aysu confirms her current title, degree status and affiliations.','Internal contradiction is confirmed; the correct appointment should not be guessed.','about-us/about-us/')
add('People','Helen: location and project stage','Confirm','Boston arrival language from 2023 remains in the present tense.','Use a dated account of the Boston work, followed by Helen’s confirmed present role and project stage.','Potentially stale, not proof that her location or degree has changed.','about-us/about-us/')
add('People','Short biographies','Editorial','Maike, Christine, Jan Philipp and Michael have very short entries.','Invite each person to supply a current role, research focus and preferred profile link.','Missing detail rather than demonstrated outdated information.','about-us/about-us/')
add('People','Remaining roster','Keep','Recent Cologne entries and an alumni section are present.','Retain the roster and personal details. Ask members to check current titles and affiliations during the next routine review.','No evidence supports moving additional people to alumni. Patricia’s move is already described historically; it is not the same contradiction as Aysu’s opening.','about-us/about-us/')
add('Andreas page','Relative chronology','Update','“last five years” describes research including the PhD without a reference date.','His research develops imaging and computational methods to investigate stimulation sites and their connections to distributed brain networks.','Replace the floating time window with an evergreen description.','about-us/about-us/andreashorn/')
add('Andreas page','Usage numbers','Update','This page gives 7,000+ downloads and 1,000+ users; the DBS page gives a different undated count.','Lead-DBS is developed by an international, multi-institutional community.','Remove competing undated numbers. Retain a metric only with a measurement definition, source and as-of date.','about-us/about-us/andreashorn/')
add('Andreas page','Duplicate biography and profile links','Confirm','Separate personal overview, social links and reviewer-profile links require their own upkeep.','Use one maintained biography. Retain verified ORCID, publication and social destinations; confirm preferred public contact.','Consolidation prevents drift. Link labels alone do not establish that destinations are broken.','about-us/about-us/andreashorn/')
add('Jobs','Vacancy status','Confirm','“Currently no open posts” has no review date.','After a staffing check: list open positions with deadlines, or display “No advertised vacancies” with the date checked.','Do not imply either that vacancies exist or that the current statement remains accurate.','about-us/jobs/')
add('Jobs','Recruitment route','Confirm','Funding guidance centres on Berlin doctoral programmes.','Interested in joining our team in Cologne? Contact us about research opportunities and fellowship-supported projects.\n\nAdd the confirmed application address and eligible programmes.','The general invitation is supported by the page. Confirm receiving contact and supervision arrangements before publishing; Berlin collaborations may continue.','about-us/jobs/')
add('Jobs','Culture and software expectations','Confirm','The culture section relies on a management label; software contributions are expected of every member.','Describe how collaboration and mentoring work in practice. Clarify which roles involve software, documentation, testing or teaching.','Ask the team whether the universal expectation still applies to the current mix of roles. This is a policy check, not an asserted change.','about-us/jobs/')
add('DBS','Research framing','Update','“cognitive disorders such as Depression” groups unlike conditions together.','We study how stimulation location and brain connectivity relate to outcomes across neurological and psychiatric conditions.','Use a research-scope statement. Any condition-specific treatment claims need appropriate current evidence and clinical context.','research-interests/deep-brain-stimulation/')
add('DBS','Impact statistics','Update','65,000+ downloads and contributions from 20+ institutions are presented without dates.','Built with the research community\n\nExplore the software, documentation and contributor community.','Remove or date and source the numbers; do not substitute estimates.','research-interests/deep-brain-stimulation/')
add('DBS','Release narrative','Update','The featured release section centres on version 3.0 in 2023.','Software and methods\n\nLink to maintained release information. Keep the 2023 story under a dated history section; separately link the 2026 v4.0 conference poster.','The poster demonstrates newer work, but does not establish a stable v4.0 release.','research-interests/deep-brain-stimulation/','https://www.netstim.org/research-interests/posters/')
add('DBS','Awards and methods','Editorial','Awards and methods predominantly describe 2015–2017 milestones.','Keep these under “Earlier milestones”. Add team-selected recent methods, grouped by research task and linked to their papers.','Historical achievements remain valid. A date is not itself a reason to delete a method.','research-interests/deep-brain-stimulation/')
add('Connectomes','Catalogue currency','Keep','The catalogue includes dTOR-985, GSP 1000 v2 and a pediatric resource.','Retain these resources and their original citations.','This is not an exclusively old catalogue. Do not replace it with a generic resource paragraph.','research-interests/normative-connectomes/')
add('Connectomes','Version and installation guidance','Confirm','Several download entries say current version; installation instructions include manual file handling.','For each dataset, display version, release date, template space, citation, licence and maintained installation instructions.','Validate against each repository before changing version labels. Download integrity and installation were not tested.','research-interests/normative-connectomes/')
add('Connectomes','Applications wording','Editorial','The DBS example broadly characterises postoperative MRI acquisition as very difficult.','Normative connectivity can support research when suitable individual connectivity data are unavailable. It does not recover an individual patient’s actual connectivity.','Keep this methodological limitation prominent. Remove the broad clinical aside or have a specialist supply device- and protocol-specific wording.','research-interests/normative-connectomes/')
add('Publications','Bibliography visibility','Confirm','The retrieved page exposes configuration-like text instead of readable citations.','Provide a readable bibliography with year, title, authors, venue, publication status and DOI; retain a fallback link to the maintained source library.','This is a retrieval limitation and possible rendering issue. A browser check is needed before calling the live widget broken or the bibliography stale.','research-interests/publications/')
add('Posters','2026 work','Keep','The page contains OHBM 2026 and DBS Expert Summit 2026 contributions.','Retain the 2026 entries. Separate posters from peer-reviewed articles and link final papers where verified.','Do not rewrite historical author affiliations to match today’s roster. Scientific results and every attachment were not individually audited.','research-interests/posters/')
add('Book','Launch copy','Editorial','“can now be ordered” retains launch-announcement wording.','Connectomic Deep Brain Stimulation\n\nExplore the book’s chapters and publisher information.','Add edition, editor, year and ISBN from the publisher record when preparing final copy. Keep contributor credit; avoid unsubstantiated superlatives.','research-interests/the-book/')
add('Videos & Talks','Archive framing','Editorial','Visible recordings are dated 2018–2021.','Talk archive\n\nBrowse recorded talks by year and topic. For further conversations, visit Stimulating Brains.','Old teaching material is not automatically inaccurate. Check each recording’s scientific context before labelling it current guidance.','research-interests/videos-talks/')
add('Videos & Talks','Conflicting event date','Confirm','One entry gives 07.09.2021 alongside a workshop labelled 2019.','Verify the event date against the programme or recording and correct either the date or event label.','Internal date mismatch; the correct value is unresolved.','research-interests/videos-talks/')
add('Stimu-Latte','Next session and launch wording','Confirm','The page retains a launch introduction and time-change notice; listed sessions end in July 2026.','Stimu-Latte is our in-person neuromodulation journal club in Cologne. Join the mailing list for session announcements.\n\nAdd the next confirmed date, time, speaker and room.','Keep the archive. Missing future dates do not establish that the series has stopped. Remove the time-change notice once no longer useful.','research-interests/stimu-latte/')
add('Stimu-Latte','Weekday consistency','Confirm','The recurring description says Wednesdays, while 21 October and 25 November 2025 were Tuesdays.','Confirm whether these were exceptions or date errors. Show each session’s actual date; describe the recurring weekday only if consistent.','Calendar mismatch is verifiable, but neither historic date should be silently changed.','research-interests/stimu-latte/')
add('Updates','Latest-news freshness','Update','The newest item on the retrieved first page is dated 4 September 2025.','Publish a sourced 2026 update, or label the existing listing “News archive” until regular updates resume.','The dated stories remain useful. Do not invent announcements from roster changes.','blog/')
add('Onboarding','Current location','Update','“Welcome to the network stimulation lab in Berlin!”','Welcome to NetStim in Cologne.','The public welcome conflicts with the current homepage location. Check the linked manual separately for location-dependent procedures.','internal/onboarding/')
add('Site-wide','Legacy destinations','Confirm','Some internal links still target netstim.berlin.','Point navigation to verified canonical destinations and preserve appropriate redirects.','A legacy hostname is not proof of a broken link. The imprint, Internal Links and Events destinations could not be retrieved in this pass.','')
add('Privacy','Policy and cookie descriptions','Confirm','Generic account/comment wording and repeated cookie entries appear in the retrieved policy and banner.','Have the responsible owner align the contact, services, retention descriptions and cookie inventory with the site actually deployed.','Editorial review flag only: no legal-compliance conclusion or tracking scan was performed. Do not replace the policy with guessed boilerplate.','privacy-policy/')
add('Local mock','Benjamin: duplicated paragraphs','Update','The local biography repeats research and hobbies; the live People page does not.','Remove the duplicate local paragraphs while preserving one complete copy.','This is a mock import defect, not outdated live content.','about-us/about-us/')
add('Local mock','Selected papers versus full coverage','Confirm','The mock has three methods papers and no full bibliography.','Label the selection clearly and preserve access to the full publication source. Include Book, Posters, Talks and Updates in the content migration inventory.','The prototype is narrower than the live site; missing routes should not become accidental content deletions.','research-interests/publications/')

coverage='Reviewed the main public content pages: Home, People (all visible profiles and alumni names), Andreas’s separate page, Jobs, DBS, Normative Connectomes, Publications, Posters, Book, Videos & Talks, Stimu-Latte, Updates (first page), public onboarding page and Privacy. Also compared the local mock. This is a page-level editorial review, not an exhaustive crawl of every archived post, scientific reference, download or embedded media item. The imprint, Internal Links and Events could not be retrieved; the external manual and dynamic bibliography remain unverified. Web results have crawl dates ranging from today to three months ago, so time-sensitive items require a direct owner check.'
from editorial_revision import revise, REFERENCES
revise(rows)
esc=html.escape
cards=[]
reference_html='<details><summary>Writing references and what changed</summary><p>Revision 2: removed the slogans, restored scientific detail and kept edits small where the original works. Reference pages inform the writing and structure, not claims about NetStim.</p><ul>'+''.join(f'<li><a href="{esc(url)}">{esc(name)}</a> — {esc(note)}</li>' for name,url,note in REFERENCES)+'</ul><p><a href="netstim-content-diff-v1.html">Previous suggestions</a></p></details>'
md=['# NetStim content comparison','', 'Reviewed 11 September 2026. Proposed edits only; live site and existing mock unchanged.', '',coverage,'','Current content is paraphrased unless quotation marks are used. “Update” means an observed issue; “Confirm” requires information before final copy; “Editorial” is optional; “Keep” records material that should be retained.','']
for i,r in enumerate(rows,1):
    source=f'<a href="{esc(r["url"])}" target="_blank" rel="noopener">Source page ↗</a>'
    if r['extra']:source+=f' · <a href="{esc(r["extra"])}" target="_blank" rel="noopener">Supporting source ↗</a>'
    source += ''.join(f' · <a href="{esc(url)}">Writing reference: {esc(name)}</a>' for name,url,note in r['references'])
    cards.append(f'''<article data-status="{r['status']}" data-search="{esc((r['page']+' '+r['title']+' '+r['before']+' '+r['after']).lower())}"><header><span class="number">{i:02d}</span><h2>{esc(r['page'])} · {esc(r['title'])}</h2><span class="badge">{r['status']}</span></header><div class="compare"><section class="before"><h3>− Current content / observation</h3><p>{esc(r['before'])}</p></section><section class="after"><h3>+ {esc(r["kind"])}</h3><p>{esc(r['after'])}</p></section></div><footer><p>{esc(r['why'])}</p>{source}</footer></article>''')
    md += [f'## {i:02d}. {r["page"]} — {r["title"]} [{r["status"]}]','', f'| Current content / observation | {r["kind"]} |','| --- | --- |',f'| {r["before"].replace(chr(10),"<br>")} | {r["after"].replace(chr(10),"<br>")} |','',r['why'],'',f'[Source page]({r["url"]})'+(f' · [Supporting source]({r["extra"]})' if r['extra'] else ''),'']
md += ['## Writing references', '', 'Revision 2 removes the slogans and preserves useful original copy. These references inform style and structure, not NetStim facts.', ''] + [f'- [{name}]({url}): {note}' for name,url,note in REFERENCES]
document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NetStim — content comparison</title><style>
*{box-sizing:border-box}body{margin:0;background:#f7f7f5;color:#202a32;font:16px/1.6 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:48px 28px}h1{font-size:36px;letter-spacing:-1px;line-height:1.15;margin:10px 0 18px}.intro{max-width:900px;color:#52616c}.eyebrow{font-size:13px;color:#426579}.controls{position:sticky;top:0;background:#f7f7f5f5;padding:16px 0;display:flex;gap:12px;z-index:1;flex-wrap:wrap}input,select,button{font:inherit;padding:9px 12px;border:1px solid #b5c0c5;background:white;border-radius:5px}input{flex:1;min-width:180px}article{background:white;border:1px solid #d6dce0;border-radius:7px;overflow:hidden;margin:20px 0 28px}article header{display:flex;align-items:center;gap:12px;padding:16px 20px}h2{font-size:18px;line-height:1.35;margin:0;flex:1}.number{color:#6c7880;font-size:13px}.badge{font-size:12px;border:1px solid #cbd4d9;padding:3px 9px;border-radius:20px}.compare{display:grid;grid-template-columns:1fr 1fr}.compare section{padding:18px 22px}.before{background:#fff0ef;border-top:1px solid #ecd6d3}.after{background:#edf8f0;border-top:1px solid #d0e6d6}.compare h3{font-size:12px;text-transform:uppercase;letter-spacing:.5px;margin:0 0 10px}.compare p{margin:0;white-space:pre-line}footer{padding:14px 22px;font-size:14px;color:#52616c}footer p{margin:0 0 7px}a{color:#155778}details{margin-top:18px}summary{cursor:pointer}#count{font-size:13px;color:#52616c;align-self:center}article[hidden]{display:none}@media(max-width:680px){main{padding:24px 16px}.compare{grid-template-columns:1fr}h1{font-size:29px}article header{flex-wrap:wrap}.controls{position:static}}@media print{.controls{display:none}body{background:white}main{max-width:none;padding:0}article{break-inside:avoid}a{color:inherit}}
</style><main><div class="eyebrow">NETSTIM · CONTENT REVIEW · REVISION 2</div><h1>What needs updating?</h1><p class="intro">Compare the existing content on the left with the recommendation on the right. Current content is summarised unless quoted. Suggested wording and editorial actions are labelled separately. No website changes have been applied.</p><p class="intro"><b>Update</b> — observed issue · <b>Confirm</b> — needs an owner check · <b>Editorial</b> — optional improvement · <b>Keep</b> — retain existing content</p><details><summary>Coverage and limitations</summary><p class="intro">'''+esc(coverage)+'''</p></details>'''+reference_html+'''<div class="controls"><input id="search" aria-label="Search review" placeholder="Search page, person or topic…"><select id="status" aria-label="Filter findings"><option value="">All findings</option><option>Update</option><option>Confirm</option><option>Editorial</option><option>Keep</option></select><button onclick="window.print()">Print / save PDF</button><span id="count"></span></div>'''+''.join(cards)+'''<p class="intro">Publication checklist: resolve the items marked Confirm, agree the selected papers, then apply the approved wording. Historical posts and affiliations should retain their original dates and context.</p></main><script>const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),status=document.querySelector('#status');function filter(){let n=0;for(const c of cards){c.hidden=!!((status.value&&c.dataset.status!==status.value)||!c.dataset.search.includes(search.value.toLowerCase()));if(!c.hidden)n++;}document.querySelector('#count').textContent=n+' of '+cards.length;}search.addEventListener('input',filter);status.addEventListener('change',filter);filter();</script></html>'''
(root/'netstim-content-diff.html').write_text(document)
(root/'netstim-content-diff.md').write_text('\n'.join(md))
(root/'findings.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False))
print(f'Created {len(rows)} comparison entries in HTML and Markdown.')
